const test=require('node:test'),assert=require('node:assert/strict'),vm=require('node:vm'),fs=require('node:fs');
// Regression: QA-012 — a previous failure filter sent a ticket's successful request to another ticket.
// Found by /qa on 2026-10-20; report: evidence/qa-2026-10-20/report.md
function workspace(){let i1={id:'I1',requests:[]},i2={id:'I2',requests:[]};let failed={id:'C1',status:'部分成功'},target={id:'C2',status:'完成'};i1.requests=[failed];i2.requests=[target];let sources=[{issue:i1,request:failed,key:'I1/C1'},{issue:i2,request:target,key:'I2/C2'}];let ctx={names:{},state:{active:'I2',issues:[i1,i2]},logSources:()=>sources,go:()=>{},save:()=>{},issue:()=>i2,issueDetail:true,requestId:'C2',taskId:null,selected:4,query:'',level:'全部',contextMode:false,sourceMode:'matched',views:{},render:()=>{},analysisForm:()=>{},showHypotheses:()=>{},chatTicket:()=>{},filterLogWorkspace:()=>{}};vm.createContext(ctx);let source=fs.readFileSync(__dirname+'/navigation.js','utf8');vm.runInContext(source.slice(0,source.indexOf('issueDetail=!!workUI.issueDetail;')),ctx);return ctx;}
test('从工单打开完成请求时清除失败页签和旧筛选，保留正确工单',()=>{let ctx=workspace();vm.runInContext("workUI.collectionMode='retry';workUI.collectionKey='I1/C1';workUI.collectionStatus='部分成功';workUI.collectionQuery='C1';go('collect')",ctx);assert.equal(ctx.selectedCollection().request.id,'C2');assert.equal(vm.runInContext('workUI.collectionMode',ctx),'push');assert.equal(vm.runInContext('workUI.collectionStatus',ctx),'');assert.equal(vm.runInContext('workUI.collectionQuery',ctx),'');assert.equal(ctx.state.active,'I2');});
